import { ExternalLink } from "lucide-react";
import { SectionReveal, RevealItem } from "@/components/ui/SectionReveal";
import attack from "@/data/attack-sector-threats.json";

// Data is generated by scripts/build-attack-data.mjs from MITRE ATT&CK Enterprise.

export function ThreatLandscape({ techniqueLimit = 8 }: { techniqueLimit?: number }) {
  const { totals, topTechniques, groups } = attack;
  const africaGroups = groups.filter((g) => g.mentionsAfrica);
  const techniques = topTechniques.slice(0, techniqueLimit);

  const stats = [
    { value: totals.sectorGroups, label: "Threat groups", description: "Documented targeting finance or government" },
    { value: totals.financial, label: "Target financial services", description: "Banks, payments, and fintech" },
    { value: totals.africa, label: "Active in Africa", description: "Named in MITRE's group reporting" },
  ];

  return (
    <section style={{ background: "#ffffff", borderTop: "1px solid rgba(0,0,0,0.3)", paddingTop: 56, paddingBottom: 56 }}>
      <div className="container-max">
        <SectionReveal variant="fade-up">
          <p className="eyebrow" style={{ color: "#ff4c00", marginBottom: 16 }}>Threat Landscape</p>
          <h2 className="font-display text-3xl md:text-4xl font-bold tracking-tight" style={{ color: "#000", maxWidth: 760 }}>
            Who targets banks and government, and how they get in
          </h2>
          <p style={{ marginTop: 12, fontSize: 16, color: "#515459", maxWidth: 680, lineHeight: 1.5 }}>
            Good threat models start from real adversaries. These figures come from MITRE ATT&amp;CK, the
            global knowledge base of documented attacker groups and the techniques they use.
          </p>
        </SectionReveal>

        <SectionReveal variant="fade-up" staggerChildren={0.1} className="grid grid-cols-3">
          {stats.map((stat, i) => (
            <RevealItem key={stat.label} variant="fade-up">
              <div className={`py-6 pr-3 sm:pr-6 lg:py-8 ${i < stats.length - 1 ? "border-r" : ""}`} style={{ borderColor: "rgba(0,0,0,0.1)" }}>
                <p className="font-display" style={{ fontSize: "clamp(2rem, 8vw, 3rem)", fontWeight: 500, lineHeight: "125%", letterSpacing: "-1.44px", color: "#000" }}>
                  {stat.value}
                </p>
                <h3 className="text-sm sm:text-base" style={{ marginTop: 8, fontWeight: 500, color: "#212429", lineHeight: 1.3 }}>{stat.label}</h3>
                <p className="hidden sm:block" style={{ marginTop: 4, fontSize: 14, color: "#919499", lineHeight: "125%" }}>{stat.description}</p>
              </div>
            </RevealItem>
          ))}
        </SectionReveal>

        <div className="grid grid-cols-1 lg:grid-cols-2" style={{ gap: "48px 64px", marginTop: 32 }}>
          {/* Most common techniques */}
          <SectionReveal variant="fade-up">
            <figure style={{ margin: 0 }}>
              <figcaption style={{ marginBottom: 16 }}>
                <span style={{ display: "block", fontSize: 18, fontWeight: 500, color: "#000" }}>Most-used attack techniques</span>
                <span style={{ display: "block", fontSize: 13, color: "#919499" }}>
                  Number of the {totals.sectorGroups} groups known to use each technique
                </span>
              </figcaption>
              <ol style={{ listStyle: "none", margin: 0, padding: 0, borderTop: "1px solid rgba(0,0,0,0.1)" }}>
                {techniques.map((t) => (
                  <li key={t.id} style={{ padding: "12px 0", borderBottom: "1px solid rgba(0,0,0,0.1)" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 12 }}>
                      <a href={t.url} target="_blank" rel="noopener noreferrer" className="group" style={{ fontSize: 15, fontWeight: 500, color: "#000" }}>
                        <span className="group-hover:text-accent transition-colors">{t.name}</span>{" "}
                        <span style={{ fontSize: 12, fontWeight: 400, color: "#919499" }}>{t.id}</span>
                      </a>
                      <span style={{ fontSize: 14, color: "#212429", fontVariantNumeric: "tabular-nums", flexShrink: 0 }}>{t.groupCount}</span>
                    </div>
                    <div style={{ marginTop: 6, height: 6, background: "#e1e4e9" }} aria-hidden>
                      <div style={{ height: "100%", width: `${(t.groupCount / totals.sectorGroups) * 100}%`, background: "#212429" }} />
                    </div>
                    <p style={{ marginTop: 6, fontSize: 12, color: "#919499" }}>{t.tactics.join(" · ")}</p>
                  </li>
                ))}
              </ol>
            </figure>
          </SectionReveal>

          {/* Groups active in Africa */}
          <SectionReveal variant="fade-up" delay={0.1}>
            <p style={{ fontSize: 18, fontWeight: 500, color: "#000" }}>Groups documented in Africa</p>
            <p style={{ fontSize: 13, color: "#919499", marginBottom: 16 }}>Targeting finance or government</p>
            <ul style={{ listStyle: "none", margin: 0, padding: 0, borderTop: "1px solid rgba(0,0,0,0.1)" }}>
              {africaGroups.map((g) => (
                <li key={g.id} style={{ padding: "14px 0", borderBottom: "1px solid rgba(0,0,0,0.1)" }}>
                  <a href={g.url} target="_blank" rel="noopener noreferrer" className="group" style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
                    <span>
                      <span className="group-hover:text-accent transition-colors" style={{ fontSize: 15, fontWeight: 500, color: "#000" }}>{g.name}</span>{" "}
                      <span style={{ fontSize: 12, color: "#919499" }}>{g.id}</span>
                      <span style={{ display: "block", marginTop: 4, fontSize: 13, color: "#515459", lineHeight: 1.5 }}>
                        {g.summary}
                      </span>
                      <span style={{ display: "block", marginTop: 4, fontSize: 12, color: "#919499" }}>
                        {g.sectors.map((s) => (s === "financial" ? "Financial" : "Government")).join(" · ")} · {g.techniqueCount} known techniques
                      </span>
                    </span>
                    <ExternalLink className="h-3.5 w-3.5 shrink-0" style={{ color: "#919499", marginTop: 4 }} aria-hidden />
                  </a>
                </li>
              ))}
            </ul>
          </SectionReveal>
        </div>

        <p style={{ marginTop: 32, fontSize: 12, color: "#919499", lineHeight: 1.6, maxWidth: 860 }}>
          Source:{" "}
          <a href="https://attack.mitre.org" target="_blank" rel="noopener noreferrer" style={{ textDecoration: "underline" }}>
            MITRE ATT&amp;CK®
          </a>{" "}
          Enterprise v{attack.attackVersion}, extracted {attack.generatedAt}. Sector and region matching is based on
          MITRE&rsquo;s published group descriptions. © The MITRE Corporation. This work is reproduced and distributed
          with the permission of The MITRE Corporation.
        </p>
      </div>
    </section>
  );
}
